import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { OPTIONS } from '../../options';

@Component({
    name: 'ErrorSplash'
})
export default class ErrorSplash extends Vue {
    @Prop({
        required: true,
        type: Boolean
    })
    public visible: boolean;

    @Prop({
        required: true,
        type: String,
        default: ''
    })
    public buttonText: string;

    @Prop({
        required: false,
        type: String,
        default: ''
    })
    public message: string;

    public options = OPTIONS;

    public onReloadGame() {
        window.location.reload();
    }
}
